cd /tmp/probe && cat > pty2.py <<'EOF'
import os, sys, pty, select, termios, struct, fcntl, time, argparse
ap = argparse.ArgumentParser()
ap.add_argument("--cols", type=int, default=80)
ap.add_argument("--rows", type=int, default=24)
ap.add_argument("--reply", action="append", default=[], help="TRIGGER::BYTES  trigger is python-escaped substring")
ap.add_argument("--delay", type=float, default=0.0)
ap.add_argument("--timeout", type=float, default=6.0)
ap.add_argument("--out", default="/tmp/probe/out.bin")
ap.add_argument("--env", action="append", default=[])
ap.add_argument("cmd", nargs=argparse.REMAINDER)
a = ap.parse_args()
def unesc(s): return s.encode().decode("unicode_escape").encode("latin1")
rules = []
for r in a.reply:
    t, b = r.split("::", 1)
    rules.append([unesc(t), unesc(b), False])
env = {}
for e in a.env:
    k, v = e.split("=", 1); env[k] = v
pid, fd = pty.fork()
if pid == 0:
    try: os.execve(a.cmd[0], a.cmd, env)
    except Exception as ex:
        os.write(2, str(ex).encode()); os._exit(127)
fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", a.rows, a.cols, 0, 0))
buf = b""; t0 = time.time(); timeline = []
alive = True
while time.time() - t0 < a.timeout:
    r, _, _ = select.select([fd], [], [], 0.05)
    if fd in r:
        try: d = os.read(fd, 65536)
        except OSError: break
        if not d: break
        timeline.append(("R", round(time.time()-t0, 4), len(d), d[:60]))
        buf += d
        for rule in rules:
            if not rule[2] and rule[0] in buf:
                rule[2] = True
                if a.delay: time.sleep(a.delay)
                os.write(fd, rule[1])
                timeline.append(("W", round(time.time()-t0, 4), len(rule[1]), rule[1][:60]))
    else:
        p, st = os.waitpid(pid, os.WNOHANG)
        if p == pid:
            code = os.waitstatus_to_exitcode(st)
            while True:
                rr, _, _ = select.select([fd], [], [], 0.1)
                if fd not in rr: break
                try: d = os.read(fd, 65536)
                except OSError: break
                if not d: break
                buf += d
            alive = False
            break
if alive:
    try:
        os.kill(pid, 9); p, st = os.waitpid(pid, 0); code = "KILLED"
    except Exception: code = "?"
open(a.out, "wb").write(buf)
sys.stderr.write("EXITCODE=%s BYTES=%d ELAPSED=%.3f\n" % (code, len(buf), time.time()-t0))
for e in timeline: sys.stderr.write("  %s t=%s n=%s %r\n" % e)
EOF
python3 pty2.py --out /tmp/probe/r.bin --env HOME=/tmp/h --env PATH=/usr/bin:/bin --env TERM=xterm-256color --env PAGER=cat /workspace/executable --style=plain t.rs 2>&1 >/dev/null | head -20

